describe('Coupon Code Validation - Error States', () => {
  beforeEach(() => {
    cy.visit('/checkout');
  });

  it('should display error message when coupon code is invalid', () => {
    // Intercept the API call to validate coupon code
    cy.intercept('POST', '/api/validate-coupon', {
      statusCode: 200,
      body: {
        isValid: false,
        error: 'Invalid coupon code format'
      }
    }).as('validateCoupon');

    // Attempt to apply an invalid coupon code
    cy.get('[data-testid="coupon-input"]').type('INVALID123');
    cy.get('[data-testid="apply-coupon-button"]').click();

    // Wait for the API response
    cy.wait('@validateCoupon');

    // Verify error message is displayed
    cy.get('[data-testid="error-message"]')
      .should('be.visible')
      .should('contain', 'Invalid coupon code format');

    // Verify coupon input is still visible
    cy.get('[data-testid="coupon-input"]').should('be.visible');

    // Verify success button is disabled
    cy.get('[data-testid="success-button"]').should('be.disabled');
  });

  it('should display error message when coupon code is expired', () => {
    // Intercept the API call to validate coupon code
    cy.intercept('POST', '/api/validate-coupon', {
      statusCode: 200,
      body: {
        isValid: false,
        error: 'Coupon code has expired'
      }
    }).as('validateCouponExpired');

    // Attempt to apply an expired coupon code
    cy.get('[data-testid="coupon-input"]').type('EXPIRED123');
    cy.get('[data-testid="apply-coupon-button"]').click();

    // Wait for the API response
    cy.wait('@validateCouponExpired');

    // Verify error message is displayed
    cy.get('[data-testid="error-message"]')
      .should('be.visible')
      .should('contain', 'Coupon code has expired');

    // Verify coupon input is still visible
    cy.get('[data-testid="coupon-input"]').should('be.visible');

    // Verify success button is disabled
    cy.get('[data-testid="success-button"]').should('be.disabled');
  });
});
